(()=>{const division=v=>/women?/i.test(v)?'women':/grom/i.test(v)?'groms':/(men|open)/i.test(v)?'open':'';const normal=v=>String(v).toLowerCase().replace(/women'?s?|men'?s?|groms?|open|qualifiers?|finals?/g,'').replace(/[^a-z0-9]+/g,' ').trim();function suggest(){document.querySelectorAll('.unassigned-race').forEach(row=>{const label=row.querySelector('span'),select=row.querySelector('select');if(!label||!select||select.dataset.suggested)return;const wanted=normal(label.textContent),group=division(label.textContent),matches=[...select.options].filter(o=>normal(o.textContent.split('→').pop())===wanted&&(!group||o.textContent.trim().toLowerCase().startsWith(group)));if(matches.length===1){select.value=matches[0].value;select.dataset.suggested='true';const hint=document.createElement('small');hint.className='suggestion';hint.textContent='Suggested';row.append(hint)}})}new MutationObserver(suggest).observe(document.body,{childList:true,subtree:true});addEventListener('DOMContentLoaded',()=>{suggest();document.addEventListener('click',async e=>{const save=e.target.closest('#save-setup');if(!save)return;const assignments=[...document.querySelectorAll('.unassigned-race')].map(row=>{const raceId=+row.querySelector('select').value;if(!raceId)return null;const choice=row.querySelector('select').selectedOptions[0].textContent.split('→').map(x=>x.trim()),eventId=row.querySelector('.assign-from-bottom').dataset.e,name=row.querySelector('span').textContent;return {eventId,tournament:choice[0],level:choice[1],race:choice[2],raceId,name}}).filter(Boolean);if(!assignments.length)return;e.preventDefault();e.stopImmediatePropagation();save.textContent='Saving assignments…';try{await req('/api/admin/assignments',{assignments});await req('/api/admin/save',{});location.reload()}catch(err){save.textContent='Save failed: '+err.message}},true)})})();

